// src/api.ts
import axios from "axios";

const api = axios.create({
  baseURL: "http://localhost:5000/api",
});

// Automatically attach correct token based on route
api.interceptors.request.use(
  (config) => {
    const path = window.location.pathname;

    // BUSINESS ROUTES TAKE PRIORITY WHEN INSIDE /business/*
    const isBusinessRoute = path.startsWith("/business");

    let token = null;

    const businessToken = localStorage.getItem("businessToken");
    const customerToken = localStorage.getItem("customerToken");

    if (isBusinessRoute) {
      // Use business token first
      if (businessToken) token = businessToken;
      else if (customerToken) token = customerToken; // fallback
    } else {
      // Customer pages use customer token first
      if (customerToken) token = customerToken;
      else if (businessToken) token = businessToken; // fallback
    }

    if (token) {
      config.headers = config.headers || {};
      config.headers.Authorization = `Bearer ${token}`;
    }

    return config;
  },
  (error) => Promise.reject(error)
);

export default api;
